"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";

export default function CrearPropuesta() {
  const router = useRouter();

  const [titulo, setTitulo] = useState("");
  const [cantidadAlumnos, setCantidadAlumnos] = useState(0);
  const [fecha, setFecha] = useState("");
  const [horario, setHorario] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      const res = await fetch(
        "http://127.0.0.1:8090/api/collections/Salidas_Alumnos/records",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            Titulo_Salida: titulo,
            Cantidad_Alumnos: cantidadAlumnos,
            Fecha_Salida: fecha,
            Horario_Salida: horario,
          }),
        }
      );

      if (!res.ok) {
        throw new Error("Error al guardar");
      }

      // 🔥 Redirige al home después de guardar
      router.push("/");

    } catch (error) {
      console.error("Error:", error);
      alert("No se pudo guardar la propuesta.");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-8">
      <form
        onSubmit={handleSubmit}
        className="w-full max-w-md space-y-6"
      >
        <h1 className="text-2xl font-bold text-center">
          Nueva Propuesta
        </h1>

        <input
          type="text"
          placeholder="Título"
          value={titulo}
          onChange={(e) => setTitulo(e.target.value)}
          className="w-full border p-2 rounded"
          required
        />

        <input
          type="number"
          placeholder="Cantidad de alumnos"
          value={cantidadAlumnos}
          onChange={(e) => setCantidadAlumnos(Number(e.target.value))}
          className="w-full border p-2 rounded"
          required
        />

        <input
          type="date"
          value={fecha}
          onChange={(e) => setFecha(e.target.value)}
          className="w-full border p-2 rounded"
          required
        />

        <input
          type="time"
          value={horario}
          onChange={(e) => setHorario(e.target.value)}
          className="w-full border p-2 rounded"
          required
        />

        <Button type="submit" className="w-full">
          Guardar Propuesta
        </Button>
      </form>
    </div>
  );
}